CREATE TABLE IF NOT EXISTS records (kind VARCHAR(40) NOT NULL, id VARCHAR(64) NOT NULL, data LONGTEXT NOT NULL, PRIMARY KEY(kind,id));
CREATE TABLE IF NOT EXISTS credentials (id VARCHAR(64) PRIMARY KEY, ciphertext LONGTEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admins (name VARCHAR(100) PRIMARY KEY, password VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (id VARCHAR(32) PRIMARY KEY, resource VARCHAR(100) NOT NULL, kind VARCHAR(40) NOT NULL, payload LONGTEXT NOT NULL, status VARCHAR(30) NOT NULL, owner VARCHAR(32), lease BIGINT NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, created BIGINT NOT NULL, result LONGTEXT NOT NULL);
CREATE TABLE IF NOT EXISTS resource_locks (resource VARCHAR(100) PRIMARY KEY, operation VARCHAR(32) NOT NULL);
CREATE TABLE IF NOT EXISTS steps (id VARCHAR(32) PRIMARY KEY, operation VARCHAR(32) NOT NULL, at BIGINT NOT NULL, step VARCHAR(80) NOT NULL, data LONGTEXT NOT NULL);
